import Vue from 'vue';
import VueApollo from 'vue-apollo';
import { parseBoolean } from '@gitlab/frontend-utils';
import Translate from '~/vue_shared/translate';
import createDefaultClient from '~/lib/graphql';
import { convertObjectPropsToCamelCase } from '~/lib/utils/common_utils';
import csrf from '~/lib/utils/csrf';
import AdminUsersApp from './components/app.vue';
import AdminUsersFilterApp from './components/admin_users_filter_app.vue';
import DeleteUserModal from './components/modals/delete_user_modal.vue';
import RemoveOrganizationUserModal from './components/modals/remove_organization_user_modal.vue';
import UserActions from './components/user_actions.vue';

Vue.use(Translate);
Vue.use(VueApollo);

const apolloProvider = new VueApollo({
  defaultClient: createDefaultClient(),
});

const initApp = ({ el, component, userPropKey, name, props = {}, provide = {} }) => {
  if (!el) {
    return false;
  }

  const { [userPropKey]: user, paths } = el.dataset;

  return new Vue({
    el,
    name,
    provide: {
      ...provide,
    },
    apolloProvider,
    render: (createElement) =>
      createElement(component, {
        props: {
          [userPropKey]: convertObjectPropsToCamelCase(JSON.parse(user), { deep: true }),
          paths: convertObjectPropsToCamelCase(JSON.parse(paths)),
          ...props,
        },
      }),
  });
};

export const initAdminUsersFilterApp = () => {
  const el = document.querySelector('#js-admin-users-filter-app');

  if (!el) {
    return false;
  }

  return new Vue({
    el,
    name: 'AdminUsersFilterAppRoot',
    apolloProvider,
    render: (createElement) =>
      createElement(AdminUsersFilterApp, {
        props: {
          showFilterTokens: parseBoolean(el.dataset.showFilterTokens),
        },
      }),
  });
};

export const initAdminUserActions = (el = document.querySelector('#js-admin-user-actions')) =>
  initApp({
    el,
    component: UserActions,
    userPropKey: 'user',
    name: 'AdminUserActionsRoot',
    props: { showButtonLabels: true },
  });

export const initAdminUsersApp = (el = document.querySelector('#js-admin-users-app')) =>
  initApp({
    el,
    component: AdminUsersApp,
    userPropKey: 'users',
    name: 'AdminUsersAppRoot',
    provide: { isAtSeatsLimit: parseBoolean(el?.dataset?.isAtSeatsLimit) },
  });

export const initDeleteUserModals = () => {
  return new Vue({
    name: 'DeleteUserModalRoot',
    render: (createElement) =>
      createElement(DeleteUserModal, {
        props: {
          csrfToken: csrf.token,
        },
      }),
  }).$mount();
};

export const initRemoveFromOrganizationModal = () => {
  return new Vue({
    name: 'RemoveOrganizationUserModalRoot',
    apolloProvider,
    render: (createElement) => createElement(RemoveOrganizationUserModal),
  }).$mount();
};
